import{_ as a,o as n,c as p,a6 as e}from"./chunks/framework.De615z8S.js";const _=JSON.parse('{"title":"Amazon副图分工与逐张制作指令","description":"","frontmatter":{"id":"P11","title":"Amazon副图分工与逐张制作指令","chapter":"13","topic":"cross-border","status":"已公开","evidence_status":"完整模板，尚未执行图像任务或流程验证","last_modified":"2026-10-14T00:00:00.000Z","resource_ids":["ecommerce-skills","visual-copywriting"],"order":111},"headers":[],"relativePath":"prompts/P11.md","filePath":"prompts/P11.md"}'),l={name:"prompts/P11.md"};function t(i,s,c,o,r,d){return n(),p("div",null,[...s[0]||(s[0]=[e(`<h1 id="p11-amazon副图分工与逐张制作指令" tabindex="-1">P11 Amazon副图分工与逐张制作指令 <a class="header-anchor" href="#p11-amazon副图分工与逐张制作指令" aria-label="Permalink to &quot;P11 Amazon副图分工与逐张制作指令&quot;">​</a></h1><p>类型：策划＋单图任务。替换项目：真实细节图、商品事实、用途、准确短文案。下面提供完整填写示范，虚构商品DN01只作练习；正式使用时替换事实与素材。示范未附照片、未执行任务。</p><p><a href="./../ecommerce/amazon-listing">逐步教程</a></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>请为Amazon US商品页规划5张副图，并给每张完整可执行的制作指令。本次先交规划，不一次生成5张。</span></span>
<span class="line"><span>以下DN01／DeskNest是虚构练习数据，不代表实际品牌或商品；正式任务必须换成已核实的商品记录。</span></span>
<span class="line"><span>练习事实：带盖桌面收纳盒；白色ABS；外尺寸长220×宽150×高120 mm；可拆隔板1个。</span></span>
<span class="line"><span>发货内容：盒体1、盖子1、隔板1。文具等场景道具不随商品发货。</span></span>
<span class="line"><span>容积、耐温、承重、防水、食品接触、认证和回收属性均未知，不补相关声明。</span></span>
<span class="line"><span>图片输入如有：图1是真实商品外观依据；图2是实际细节；图3仅参考背景和构图，不使用其商品、Logo或参数。</span></span>
<span class="line"><span>未附实拍时先给素材清单和可执行方案；不要臆画正式商品或未拍摄结构。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>5个任务分别是：书桌使用场景；开盖与可拆隔板；外尺寸；发货内容；使用步骤。</span></span>
<span class="line"><span>每张都输出：解决的买家问题、实际素材、构图、准确英文短标签、完整制作任务词、后期排版位置、检查项与未确认内容。</span></span>
<span class="line"><span>场景：白天书桌、柔和侧光、真实主体，文具仅作获准环境道具；明确不要让道具进入发货清单。</span></span>
<span class="line"><span>结构：必须依据开盖和隔板实拍，缺图列补拍，不画出未知内结构。</span></span>
<span class="line"><span>尺寸：L220×W150×H120 mm，保留外尺寸标签，不猜容积或内尺寸。</span></span>
<span class="line"><span>配件：Box ×1, lid ×1, divider ×1；图像与清单逐项对应。</span></span>
<span class="line"><span>使用：只使用已确认的打开、放置文具、合盖步骤；没有实际动作依据时列待确认。</span></span>
<span class="line"><span>每张练习母版1:1，准确文字独立可编辑排版。场景、结构与尺寸分别制作，不能用一张拼贴代替5项任务。</span></span>
<span class="line"><span>本次范围按上述任务执行；没有图像能力时只交方案并写明状态。</span></span>
<span class="line"><span>实际执行时保留真实商品层与准确文字，逐项核对形状、颜色、盖子、隔板、配件、单位和文字。</span></span>
<span class="line"><span>目标尺寸与工具实际输出分别报告；不把画质形容词、计划路径或未创建的PSD当作已交付结果。</span></span>
<span class="line"><span>最终列：已完成、需要补的素材、无法确认的项目、实际存在的文件与下一步。</span></span></code></pre></div><p>检查：输入角色清楚、事实与未知分开、输出范围明确，实际文件与后台状态据实记录。</p>`,5)])])}const h=a(l,[["render",t]]);export{_ as __pageData,h as default};
